function this.FormatTimeHMAndDW(time)
    time = math.modf(time)
    local hour = math.modf(time / 3600)
    local minute = math.modf(time % 3600 / 60)
    local fmtTime = string.format("%02dh%02dm", hour, minute)
    return fmtTime
end

