function this.FormatTimeHMS(time)
    time = math.modf(time)
    local hour = math.modf(time / 3600)
    local minute = math.modf(time % 3600 / 60)
    local second = time % 60
    local fmtTime = string.format("%02d:%02d:%02d", hour, minute, second)
