end
--时分秒
function this.FormatTimeHMSD(time)
    time = math.modf(time)
    local minute = time // 60 % 60
    local hour = time // 3600 % 24
    local second = time % 60
    local day = time // 86400
    if day >= 1 then
        return string.format("%d天:%02d时:%02d分", day, hour, minute)
    else
        return string.format("%02d:%02d:%02d", hour, minute, second)
    end
end
