---格式化数据
function this.FormatNumber(count, integer_bit_notZero, isReplace_chinese_character)
    if not integer_bit_notZero then
        local str = count
        count = tonumber(count)
        if count >= 100000 and count < 10000000 then
            local num = string.format("%0.1f", count / 10000)
            str = num .. (isReplace_chinese_character and "w" or "万")
        elseif count > 10000000 then
            local num = string.format("%0.1f", count / 100000000)
            str = num .. (isReplace_chinese_character and "y" or "亿")
        end
        return str
    else
        local str = count
        if count >= 10000 and count < 100000000 then
            local num = string.format("%0.1f", count / 10000)
            if tonumber(num) == math.floor(num) then
                num = math.floor(num)
            end
            str = num .. (isReplace_chinese_character and "w" or "万")
        elseif count >= 100000000 then
            local num = tonumber(string.format("%0.1f", count / 100000000))
            if num < 10000 then
                str = (isReplace_chinese_character and "y" or "亿")
            elseif num >= 10000 and num < 100000000 then
                num = string.format("%0.1f", num / 10000)
                str = (isReplace_chinese_character and "z" or "兆")
            elseif num >= 100000000 then
                num = string.format("%0.1f", num / 100000000)
                str = (isReplace_chinese_character and "j" or "京")
            end
            if tonumber(num) == math.floor(num) then
                num = math.floor(num)
            end
            str = num .. str
        end
        return str
    end
end


--代币id
local coinId

--获得代币id
local function GetCoinId()
    if coinId then
        return coinId
    end
    ---默认代币id
    coinId = 30510308
    local tbl = SL:GetConfigTable("cfg_item")
    for _, v in pairs(tbl) do
        if v.type == 3 and v.subType == 51 then
            coinId = v.id
            return coinId
        end
    end

    return coinId
end

---@充值通用接口(需要使用代币调用这个)
---@param rechargeTbl cfg_recharge_column @充值表
---@param count number @充值数量
---@param extraParams table @透传参数(可选参数
function this.SDKPay(rechargeTbl, count, extraParams)
    if not rechargeTbl then
        logError("Not found rechargeTbl")
        return
    end

    local haveCount = SL:GetBagItemCount(GetCoinId())
    local needCount = rechargeTbl.amount
    if haveCount >= needCount then
        ---有代币
        SL:SendLuaNetMsg(LuaMessageIdToSever.REQ_RECHARGE, { rechargeId = rechargeTbl.id, count = count, extraParams = extraParams })
        return
    end

    SL:SDKPay(rechargeTbl, count, extraParams)
end
--考虑时区 单位秒
---@param serverDate table 服务器日期table { year = 2021, month = 12, day = 16, hour = 0,min = 0, sec = 0 }
---@return number 毫秒)
function this.DateToServerTime(serverDate)
    local DAY_SECONDS = 24 * 3600
    local TIMEZONES_SECONDS = 8 * 3600 --东八区 时区时间差
    local TIME_ZONE = os.time({ year = 1970, month = 1, day = 2, hour = 0, isdst = false })
    serverDate.isdst = false ---禁用夏令时
    local localDateTime = os.time(serverDate)
    return (localDateTime + ((DAY_SECONDS - TIMEZONES_SECONDS) - TIME_ZONE))*1000
end


