function this.tblkeytonumber(tbl)
    local newTable = {}
    for key, value in pairs(tbl) do
        local newKey = tonumber(key) or key
        if type(value) == "table" then
            newTable[newKey] = this.tblkeytonumber(value)
        else
            newTable[newKey] = value
        end
    end
    return newTable
end

function this.CheckItem(tcl)
    if tcl == nil or type(tcl) ~= "table" or not next(tcl) then
        return false
    end
    for k,v in pairs(tcl) do
        if type(k) ~= "string" then
            local itemName = v[1];
            local itemNum = tonumber(v[2]);
            local bangding = v[3];
            local item_type = v[4];--类型 1或者nil道具 2 Int变量 3开服天数
            local var_type = v[5];
            local check_str = v[6];-- == > < >= <=
            local def_str = v[7]
            if not item_type or item_type == 1 then
                local item_cfg_id = type(itemName) == "number" and itemName or SL:GetConfigMultiKeys("cfg_item", itemName,"name").id
                -- local hasCount = RoleManager.meData.bagInfo:GetItemCount(tonumber(item_cfg.id))
                local hasCount = item_cfg_id and SL:GetBagItemCount(item_cfg_id) or 0
                if itemName == "钻石" then
                    local bangding_item_cfg = SL:GetConfigMultiKeys("cfg_item", "绑定钻石","name")
                    hasCount = hasCount + SL:GetBagItemCount(bangding_item_cfg.id)
                end
                if hasCount < itemNum then
                    return false
                end
            end
        end
    end
    return true
end
---获取字符的长度
function this.GetStrLen(inputstr)
    if not inputstr or type(inputstr) ~= "string" or #inputstr <= 0 then
        return nil
    end
    local length = 0  -- 字符的个数
    local i = 1
    while true do
        local lengthCount=1
        local curByte = string.byte(inputstr, i)
        local byteCount = 1
        if curByte > 239 then
            byteCount = 4  -- 4字节字符
            lengthCount=2
        elseif curByte > 223 then
            lengthCount=2
            byteCount = 3  -- 汉字
        elseif curByte > 128 then
            byteCount = 2  -- 双字节字符
        else
            byteCount = 1  -- 单字节字符
        end
        i = i + byteCount
        length = length + lengthCount
        if i > #inputstr then
            break
        end
    end
    return length
end
---提取字符串中的><内容
function this.Extract_All_Brackets(input)
    local str = ""
    local pos = 1
    for i = 1, #input do
        local char = input:sub(i, i)
        if char == '>' then
            pos = i
        elseif char == '<' then
            if i ~= 1 then
                local newStr = string.sub(input,pos+1,i-1)
                str = str .. newStr
            end
        end
    end
    str = str..string.sub(input,pos+1,string.len(input))
    return str
end

